+}
+
+.explorer:focus-visible {
+  outline: var(--thorp-focus-outline-compact);
+  outline-offset: var(--thorp-focus-offset-wide, 6px);
+}
+
+/* 머리: 왼쪽 제목·기준월, 오른쪽 기준월 지정 칸. 좁아지면 지정 칸이 아랫줄로 내려간다. */
