+.titleGroup {
+  display: grid;
+  gap: 4px;
+  min-width: 0;
+}
+
+.kicker {
+  margin: 0;
+  color: var(--thorp-eyebrow, var(--thorp-accent-soft));
+  font: 600 var(--thorp-text-label, 0.65rem)/1.4 var(--thorp-font-display);
+  letter-spacing: 0.16em;
+}
+
+.title {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  margin: 0;
+  font-size: var(--thorp-text-heading, 1.08rem);
+  font-weight: 650;
+  letter-spacing: -0.02em;
+}
+
+.title svg {
+  flex-shrink: 0;
+  color: var(--thorp-accent-soft);
+}
+
+.meta {
+  margin: 0;
+  color: var(--thorp-muted);
+  font-size: var(--thorp-text-caption, 0.72rem);
+  font-variant-numeric: tabular-nums;
+}
+
+.meta strong {
+  color: var(--thorp-foreground);
+  font-weight: 650;
+}
+
+/* 기준월 지정. 달 입력과 찾기 버튼이 한 줄에 서고, 지정한 동안만 '최신 기준월로'가 그 옆에 선다. */
